export const getFeed = () => fetch("/api/feed").then((r) => json<FeedEvent[]>(r));

const post = (url: string, body: unknown) =>
  fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  }).then((r) => json<unknown>(r));

